def minimum_coins_dp(coins, amount):
    infinity = float("inf")
    best = [infinity] * (amount + 1)
    best[0] = 0
    for subtotal in range(1, amount + 1):
        for coin in coins:
            if coin <= subtotal and best[subtotal - coin] != infinity:
                candidate = best[subtotal - coin] + 1
                if candidate < best[subtotal]:
                    best[subtotal] = candidate
    return None if best[amount] == infinity else best[amount]

print(minimum_coins_dp([1, 3, 4], 6))
print(minimum_coins_dp([4], 6))
print(minimum_coins_dp([], 0))

def min_coins_dp(coins, amount):
    infinity = float("inf")
    best = [infinity] * (amount + 1)
    best[0] = 0
    for value in range(1, amount + 1):
        for coin in coins:
            if coin <= value and best[value - coin] != infinity:
                candidate = best[value - coin] + 1
                if candidate < best[value]:
                    best[value] = candidate
    return None if best[amount] == infinity else best[amount]

print(min_coins_dp([2, 5], 7))
print(min_coins_dp([2, 5], 3))
print(min_coins_dp([], 0))

def coin_table(coins, limit):
    best = [None] * (limit + 1)
    best[0] = 0
    for value in range(1, limit + 1):
        for coin in coins:
            if coin <= value and best[value - coin] is not None:
                candidate = best[value - coin] + 1
                if best[value] is None or candidate < best[value]:
                    best[value] = candidate
    return best

print(coin_table([2, 3], 5))
print(coin_table([], 2))
print(coin_table([5], 0))

def within_coin_budget(coins, amount, budget):
    infinity = float("inf")
    best = [infinity] * (amount + 1)
    best[0] = 0
    for value in range(1, amount + 1):
        for coin in coins:
            if coin <= value and best[value - coin] != infinity:
                candidate = best[value - coin] + 1
                if candidate < best[value]:
                    best[value] = candidate
    return best[amount] != infinity and best[amount] <= budget

print(within_coin_budget([2, 3], 7, 2))
print(within_coin_budget([2, 3], 7, 3))
print(within_coin_budget([4], 6, 9))
print(within_coin_budget([], 0, 0))

def reachable_amounts(coins, limit):
    possible = [False] * (limit + 1)
    possible[0] = True
    for value in range(1, limit + 1):
        for coin in coins:
            if coin <= value and possible[value - coin]:
                possible[value] = True
                break
    return [value for value in range(limit + 1) if possible[value]]

print(reachable_amounts([2, 3], 5))
print(reachable_amounts([], 4))
print(reachable_amounts([5], 0))
